body:
Held probe source. It builds on main `744c0847b` as `crates/motion/tests/scratch_finish_probe.rs` (untracked scratch). It builds the synthetic bar with holes, runs `finishing3d::parallel`, and prints every Feed move's XY angle, length, and end points. Use it as the base for the pinning tests of this switch.

```rust
//! SCRATCH probe (not for commit): reproduce the user's 3D Finish parallel
//! on a long bar, 2 deg slope, two openings, ball 0.3125 in, Bottom at the
//! model bottom. Classify every Feed move's XY direction.
//! Bar: x 0..24 (width), y 0..160 (length), bottom z=0, top z=5+tan(2deg)*y.
//! Hole A: x 5.5..18.5, y 88..101. Hole B: x 9.5..14.5, y 42..48. Both through.

use camcraft_motion::cl::MoveKind;
use camcraft_motion::finishing3d::{parallel, Finish3DParams, FinishPattern, GapLink};
use camcraft_motion::geometry::{Point3, Triangle};

const TAN2: f64 = 0.034_920_722_784_327_5; // tan(2 deg)

fn t(y: f64) -> f64 {
    5.0 + TAN2 * y
}

/// Quad with the winding that makes `out` the outward normal by trial:
/// pushes two triangles, and (test only) keeps quads only.
fn quad(f: &mut Vec<Triangle>, a: Point3, b: Point3, c: Point3, d: Point3) {
    f.push(Triangle::new(a, b, c));
    f.push(Triangle::new(a, c, d));
}

fn slab_with_holes() -> Vec<Triangle> {
    let (x0, x1, y0, y1) = (0.0, 24.0, 0.0, 160.0);
    let (xa0, xa1, ya0, ya1) = (5.5, 18.5, 88.0, 101.0);
    let (xb0, xb1, yb0, yb1) = (9.5, 14.5, 42.0, 48.0);
    let mut f: Vec<Triangle> = Vec::new();
    // Top and bottom strips, split by the holes' y and x edges.
    let bands: Vec<(f64, f64, Vec<(f64, f64)>)> = vec![
        (y0, yb0, vec![(x0, x1)]),
        (yb0, yb1, vec![(x0, xb0), (xb1, x1)]),
        (yb1, ya0, vec![(x0, x1)]),
        (ya0, ya1, vec![(x0, xa0), (xa1, x1)]),
        (ya1, y1, vec![(x0, x1)]),
    ];
    for (ba, bb, xs) in bands {
        for (sa, sb) in xs {
            // Top: normal about +Z.
            quad(
                &mut f,
                Point3::new(sa, ba, t(ba)),
                Point3::new(sb, ba, t(ba)),
                Point3::new(sb, bb, t(bb)),
                Point3::new(sa, bb, t(bb)),
            );
            // Bottom: normal -Z (reverse order).
            quad(
                &mut f,
                Point3::new(sa, ba, 0.0),
                Point3::new(sa, bb, 0.0),
                Point3::new(sb, bb, 0.0),
                Point3::new(sb, ba, 0.0),
            );
        }
    }
    // Outer walls.
    quad(&mut f, Point3::new(x0, y0, 0.0), Point3::new(x1, y0, 0.0), Point3::new(x1, y0, t(y0)), Point3::new(x0, y0, t(y0))); // -Y
    quad(&mut f, Point3::new(x1, y1, 0.0), Point3::new(x0, y1, 0.0), Point3::new(x0, y1, t(y1)), Point3::new(x1, y1, t(y1))); // +Y
    quad(&mut f, Point3::new(x0, y1, 0.0), Point3::new(x0, y0, 0.0), Point3::new(x0, y0, t(y0)), Point3::new(x0, y1, t(y1))); // -X
    quad(&mut f, Point3::new(x1, y0, 0.0), Point3::new(x1, y1, 0.0), Point3::new(x1, y1, t(y1)), Point3::new(x1, y0, t(y0))); // +X
    // Hole walls: normals point INTO the hole.
    for (hx0, hx1, hy0, hy1) in [(xa0, xa1, ya0, ya1), (xb0, xb1, yb0, yb1)] {
        let (ta, tb) = (t(hy0), t(hy1));
        quad(&mut f, Point3::new(hx0, hy0, 0.0), Point3::new(hx0, hy0, ta), Point3::new(hx1, hy0, ta), Point3::new(hx1, hy0, 0.0)); // +Y into hole
        quad(&mut f, Point3::new(hx1, hy1, 0.0), Point3::new(hx1, hy1, tb), Point3::new(hx0, hy1, tb), Point3::new(hx0, hy1, 0.0)); // -Y into hole
        quad(&mut f, Point3::new(hx0, hy0, 0.0), Point3::new(hx0, hy1, 0.0), Point3::new(hx0, hy1, tb), Point3::new(hx0, hy0, ta)); // +X into hole
        quad(&mut f, Point3::new(hx1, hy1, 0.0), Point3::new(hx1, hy0, 0.0), Point3::new(hx1, hy0, ta), Point3::new(hx1, hy1, tb)); // -X into hole
    }
    f
}

#[test]
fn scratch_probe_parallel_directions() {
    let facets = slab_with_holes();
    let p = Finish3DParams {
        pattern: FinishPattern::Parallel,
        stepover: None,
        tool_diameter: 7.9375,
        tolerance: 0.01,
        clearance_z: 10.0,
        retract_z: None,
        top_z: t(160.0),
        bottom_z: 9.75, // 0.24 mm under the high top edge: the "Bottom 0.3in" case
        feed: 500.0,
        plunge_feed: 250.0,
        climb: true,
        ramp: false,
        entry_ramp: false,
        min_step: None,
        ramp_angle: 45.0,
        steep_stepover: None,
        pencil_reference: None,
        gap_link: GapLink::Jump,
    };
    let path = match parallel(&facets, &p) {
        Ok(t) => t,
        Err(e) => panic!("parallel refused: {e}"),
    };
    let mut xfam = 0usize;
    let mut yfam: Vec<(f64, String)> = Vec::new();
    let mut other: Vec<(f64, String)> = Vec::new();
    let (mut plunge, mut rapid, mut feed_n, mut tiny) = (0usize, 0usize, 0usize, 0usize);
    for m in &path.moves {
        match m.kind {
            MoveKind::Plunge => plunge += 1,
            MoveKind::Rapid => rapid += 1,
            MoveKind::Feed => feed_n += 1,
            _ => {}
        }
        if m.kind != MoveKind::Feed {
            continue;
        }
        let (dx, dy) = (m.to.x - m.from.x, m.to.y - m.from.y);
        let xy = (dx * dx + dy * dy).sqrt();
        if xy < 0.5 {
            tiny += 1;
            continue; // vertical / tiny
        }
        let deg = dy.abs().max(f64::EPSILON).atan2(dx.abs()).to_degrees();
        let desc = format!(
            "ang {deg:6.1} len {xy:8.2} from ({:6.2},{:6.2},{:6.2}) to ({:6.2},{:6.2},{:6.2})",
            m.from.x, m.from.y, m.from.z, m.to.x, m.to.y, m.to.z
        );
        if deg < 45.0 {
            xfam += 1;
        } else if deg >= 67.5 {
            yfam.push((xy, desc));
        } else {
            other.push((xy, desc));
        }
    }
    println!("probe: moves {} feed {feed_n} plunge {plunge} rapid {rapid} tiny {tiny}", path.moves.len());
    println!("probe: Feed XY moves along X (ang<45): {xfam}");
    println!("probe: Feed XY moves along Y (ang>=67.5): {}", yfam.len());
    yfam.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap());
    other.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap());
    for (_, d) in yfam.iter().take(80) {
        println!("  Y-family: {d}");
    }
    for (_, d) in other.iter().take(10) {
        println!("  oblique:  {d}");
    }
    for n in &path.notes {
        println!("  note: {n}");
    }
}

